-- ═══ 2. ДИСПЕТЧЕР: байт инструкции -> номер операции ═══
local OPNAME = {[1]="T21", [2]="POP", [6]="GET_UPVAL", [8]="NOP8", [10]="VARARG", [12]="T4", [20]="SETLIST_MARK", [21]="NOP21", [23]="NEG", [24]="T6", [26]="PUSH_NILS", [27]="SET_TABLE_KEEP", [29]="SET_UPVAL", [30]="T20", [42]="SETLIST", [44]="PUSH_BOOL", [46]="NOP46", [48]="NOP48", [55]="CLOSURE", [63]="T8", [65]="T13", [70]="BINOP", [75]="NOP75", [79]="BNOT", [83]="T15", [85]="CALL_MARK", [88]="GET_LOCAL", [92]="NOP92", [93]="NOP93", [94]="NOP94", [95]="T5", [96]="T16", [97]="T2", [99]="T14", [103]="SET_UPVAL_CELL", [104]="GET_UPVAL", [105]="DUP", [106]="CALL", [107]="PUSH_CONST", [111]="NEW_TABLE", [112]="RETURN", [114]="NOP114", [115]="NOP115", [118]="NOP118", [119]="RET_MARK", [124]="T10", [129]="T7", [131]="COND_JUMP", [136]="NOP136", [140]="NOP140", [143]="NOP143", [145]="NOP145", [148]="T12", [149]="ADJUST", [150]="SET_UPVAL_CELL_REF", [154]="CLEAR_UPVAL", [156]="T21b", [157]="MK", [159]="FOR_PREP", [162]="T9", [164]="PUSH_SZN", [166]="SET_TABLE_POP3", [169]="FOR_GEN", [176]="T1", [180]="T3", [182]="NOP182", [187]="T0", [191]="NOT", [197]="SET_GLOBAL", [199]="NOP199", [202]="GET_GLOBAL", [203]="SET_LOCAL", [208]="NOP208", [213]="COND_JUMP2", [222]="GET_UPVAL_CELL", [224]="PUSH_NIL", [227]="NOP", [229]="LEN", [230]="GET_TABLE", [232]="NOP232", [234]="JUMP", [242]="SELF", [243]="SET_TABLE_IMM", [247]="NEW_UPVAL"}
local Z = {119, 33, 97, 105, 79, 185, 148, 105, 202, 156, 163, 103, 254, 137, 240, 156, 199, 150, 227, 33, 164, 149, 65, 55, 254, 169, 55, 118, 95, 254, 124, 83, 224, 229, 20, 208, 100, 169, 164, 103, 10, 229, 246, 23, 70, 44, 232, 224, 229, 114, 234, 106, 94, 164, 120, 202, 198, 118, 96, 24, 23, 157, 1, 227, 24, 162, 199, 88, 83, 129, 111, 95, 208, 27, 94, 38, 191, 79, 136, 176, 2, 21, 106, 23, 88, 247, 21, 232, 202, 131, 150, 162, 113, 203, 185, 21, 157, 171, 169, 159, 99, 254, 88, 75, 111, 27, 20, 227, 94, 131, 21, 95, 103, 234, 148, 79, 63, 229, 124, 6, 100, 103, 44, 146, 48, 222, 137, 182, 30, 29, 27, 242, 129, 249, 94, 42, 243, 65, 83, 129, 254, 12, 143, 208, 137, 124, 83, 92, 208, 240, 247, 104, 191, 92, 63, 148, 187, 197, 113, 202, 198, 12, 1, 254, 107, 230, 30, 230, 154, 44, 12, 159, 55, 65, 154, 65, 112, 140, 243, 197, 197, 227, 107, 176, 169, 83, 120, 30, 82, 98, 119, 112, 83, 164, 157, 8, 104, 224, 29, 115, 137, 203, 230, 46, 70, 242, 94, 232, 83, 230, 26, 48, 171, 92, 93, 246, 93, 93, 6, 46, 120, 30, 180, 97, 222, 224, 166, 106, 98, 213, 30, 124, 24, 85, 30, 131, 149, 99, 76, 93, 136, 98, 38, 222, 70, 229, 242, 230, 85, 29, 154, 113, 185, 95, 213}

-- ═══ 3. ИСПОЛНИТЕЛЬ ═══
local MARK_CALL, MARK_RET, MARK_LIST = {}, {}, {}
local SHARED_UPS = {}  -- оригинальный _rJMpF: общие upvalue замыканий без mdg

local ARITH = {
    [28]=function(x,y) return x+y end, [24]=function(x,y) return x-y end,
    [141]=function(x,y) return x*y end, [55]=function(x,y) return x/y end,
    [208]=function(x,y) return x//y end, [45]=function(x,y) return x%y end,
    [98]=function(x,y) return x^y end, [137]=function(x,y) return x..y end,
    [103]=function(x,y) return x==y end, [213]=function(x,y) return x~=y end,
    [44]=function(x,y) return x<y end, [192]=function(x,y) return x>y end,
    [8]=function(x,y) return x<=y end, [9]=function(x,y) return x>=y end,
    [14]=function(x,y) return bit32.band(x,y) end, [191]=function(x,y) return bit32.bor(x,y) end,
    [140]=function(x,y) return bit32.bxor(x,y) end, [6]=function(x,y) return bit32.lshift(x,y) end,
    [52]=function(x,y) return bit32.rshift(x,y) end,
}
local BIT1 = { [23]="neg", [79]="bnot" }

local function read32(code, off)
    local b1,b2,b3,b4 = string.byte(code, off, off+3)
    b1, b2, b3, b4 = b1 or 0, b2 or 0, b3 or 0, b4 or 0
    return (b1*256+b2) + (b3*256+b4)*65536
end

local Frame = {}
Frame.__index = Frame

local VM -- forward

local function spawn(rid, upvals, ...)
    local rec = CHUNKS[rid]
    local F = setmetatable({}, Frame)
    F.rec = rec; F.ri = {}; F.vl = {}; F.vt = {}; F.zd = upvals or SHARED_UPS
    F.ci = {}; F.szn = math.random(0, 2147483646)
    local jo = rec.jo
    local nargs = select("#", ...)
    local qi = 1
    for j = 1, #jo do
        local v = select(j, ...)
        if rec.qtv[qi] == j then
            F.ri[jo[j]] = {v}; qi = qi + 1
        else
            F.ri[jo[j]] = v
        end
    end
    if rec.xsl and nargs > #jo then
        local extra = {}
        for j = #jo + 1, nargs do extra[#extra+1] = select(j, ...) end
        F.ci = extra
    end
    return VM(F)
end

local function upvRef(F, k)
    local c = F.zd[k]
    if c == nil then return nil end
    return c[1]
end

function VM(F)
    local rec = F.rec
    local code = rec.code
    local st, sp = F.vt, 0
    local pc = rec.iuq or 1
    while true do
        local raw = string.byte(code, pc)
        local h = Z[raw]
        if h == 227 or h == 199 or h == 94 or h == 136 or h == 21 or h == 75 or h == 114
           or h == 115 or h == 93 or h == 48 or h == 140 or h == 232 or h == 92 or h == 1
           or h == 8 or h == 118 or h == 143 or h == 46 or h == 182 or h == 145 or h == 208 then
            pc = pc + 1
        elseif h == 224 then -- PUSH_NIL
            sp = sp + 1; st[sp] = nil; pc = pc + 1
        elseif h == 44 then -- PUSH_BOOL
            sp = sp + 1; st[sp] = (read32(code, pc+1) == 1); pc = pc + 5
        elseif h == 107 then -- PUSH_CONST
            sp = sp + 1; st[sp] = rec.consts[read32(code, pc+1)]; pc = pc + 5
        elseif h == 105 then -- DUP
            sp = sp + 1; st[sp] = st[sp-1]; pc = pc + 1
        elseif h == 2 then -- POP
            sp = sp - 1; pc = pc + 1
        elseif h == 164 then -- PUSH_SZN (шум: случайное число)
            sp = sp + 1; st[sp] = F.szn; pc = pc + 1
        elseif h == 85 or h == 20 or h == 119 then -- маркеры
            sp = sp + 1; st[sp] = (h == 85 and MARK_CALL) or (h == 20 and MARK_LIST) or MARK_RET
            pc = pc + 1
        elseif h == 6 then -- GET_UPVAL (своя ячейка)
            local c = F.ri[read32(code, pc+1)]
            sp = sp + 1; st[sp] = c and c[1]; pc = pc + 5
        elseif h == 103 then -- SET_UPVAL_CELL
            local v = st[sp]; sp = sp - 1
            local idx = read32(code, pc+1)
            local c = F.ri[idx]
            if not c then c = {}; F.ri[idx] = c end
            c[1] = v; pc = pc + 5
        elseif h == 222 then -- GET_UPVAL_CELL (ref)
            sp = sp + 1; st[sp] = F.ri[read32(code, pc+1)]; pc = pc + 5
        elseif h == 150 then -- SET_UPVAL_CELL_REF
            local v = st[sp]; sp = sp - 1
            F.ri[read32(code, pc+1)] = v; pc = pc + 5
        elseif h == 154 then -- CLEAR_UPVAL
            F.ri[read32(code, pc+1)] = nil; pc = pc + 5
        elseif h == 247 then -- NEW_UPVAL
            F.ri[read32(code, pc+1)] = {}; pc = pc + 5
        elseif h == 104 then -- GET_UPVAL (от родителя)
            local c = F.zd[read32(code, pc+1)]
            sp = sp + 1; st[sp] = c and c[1]; pc = pc + 5
        elseif h == 29 then -- SET_UPVAL (от родителя)
            local v = st[sp]; sp = sp - 1
            local idx = read32(code, pc+1)
            local c = F.zd[idx]
            if not c then c = {}; F.zd[idx] = c end
            c[1] = v; pc = pc + 5
        elseif h == 202 then -- GET_GLOBAL
            local n = rec.consts[read32(code, pc+1)]
            sp = sp + 1; st[sp] = VMENV[n]; pc = pc + 5
        elseif h == 197 then -- SET_GLOBAL
            local v = st[sp]; sp = sp - 1
            VMENV[rec.consts[read32(code, pc+1)]] = v; pc = pc + 5
        elseif h == 88 then -- GET_LOCAL
            sp = sp + 1; st[sp] = F.vl[read32(code, pc+1)]; pc = pc + 5
        elseif h == 203 then -- SET_LOCAL
            local v = st[sp]; sp = sp - 1
            F.vl[read32(code, pc+1)] = v; pc = pc + 5
        elseif h == 187 or h == 176 or h == 97 or h == 180 or h == 12 or h == 95 or h == 24
             or h == 129 or h == 63 or h == 162 or h == 124 or h == 148 or h == 65 or h == 99
             or h == 83 or h == 96 or h == 30 or h == 156 or h == 111 then -- NEW_TABLE (presize)
            local n = ({[187]=0,[176]=1,[97]=2,[180]=3,[12]=4,[95]=5,[24]=6,[129]=7,[63]=8,
                        [162]=9,[124]=10,[148]=12,[65]=13,[99]=14,[83]=15,[96]=16,[30]=20,[156]=21})[h]
            sp = sp + 1; st[sp] = {}; if n and n > 0 then table.insert(st[sp], nil) end
            pc = pc + 1
        elseif h == 230 then -- GET_TABLE (ключ со стека)
            local k = st[sp]; local t = st[sp-1]; sp = sp - 2
            sp = sp + 1; st[sp] = t[k]; pc = pc + 1
        elseif h == 27 then -- SET_TABLE_KEEP (таблица остаётся)
            local v = st[sp]; local k = st[sp-1]; sp = sp - 2
            st[sp][k] = v; pc = pc + 1
        elseif h == 166 then -- SET_TABLE_POP3
            local v = st[sp]; local k = st[sp-1]; local t = st[sp-2]; sp = sp - 3
            t[k] = v; pc = pc + 1
        elseif h == 243 then -- SET_TABLE_IMM (ключ-константа, таблица остаётся)
            local v = st[sp]; sp = sp - 1
            st[sp][read32(code, pc+1)] = v; pc = pc + 5
        elseif h == 242 then -- SELF
            local base = st[sp]; sp = sp - 1
            local m = rec.consts[read32(code, pc+1)]
            sp = sp + 1; st[sp] = base[m]
            sp = sp + 1; st[sp] = base
            pc = pc + 5
        elseif h == 106 then -- CALL
            local j = sp
            while st[j] ~= MARK_CALL do j = j - 1 end
            local f = st[j+1]
            local nres = read32(code, pc+1)
            local args = {}
            for k = j+2, sp do args[#args+1] = st[k] end
            sp = j - 1
            local res = table.pack(f(table.unpack(args, 1, #args)))
            if nres == 0 then
                for k = 1, res.n do sp = sp + 1; st[sp] = res[k] end
            elseif nres == 2 then
                sp = sp + 1; st[sp] = res[1]
            elseif nres > 2 then
                for k = 1, nres - 1 do sp = sp + 1; st[sp] = res[k] end
            end -- nres == 1: результатов нет
            pc = pc + 5
        elseif h == 149 then -- ADJUST (обрезка multireturn до a)
            local a = read32(code, pc+1)
            local j = sp
            while st[j] ~= MARK_CALL do j = j - 1 end
            local vals = {}
            for k = j+1, sp do vals[#vals+1] = st[k] end
            sp = j - 1
            local n = (a == 0) and #vals or a
            for k = 1, n do sp = sp + 1; st[sp] = vals[k] end
            pc = pc + 5
        elseif h == 10 then -- VARARG
            local a = read32(code, pc+1)
            if a == 0 then
                for k = 1, #F.ci do sp = sp + 1; st[sp] = F.ci[k] end
            else
                for k = 1, a - 1 do sp = sp + 1; st[sp] = F.ci[k] end
            end
            pc = pc + 5
        elseif h == 42 then -- SETLIST
            local start = read32(code, pc+1)
            local j = sp
            while st[j] ~= MARK_LIST do j = j - 1 end
            local t = st[j-1]
            for k = j+1, sp do t[start + k - j - 1] = st[k] end
            sp = j - 1
            pc = pc + 5
        elseif h == 70 then -- BINOP
            local key = read32(code, pc+1)
            local y, x = st[sp], st[sp-1]; sp = sp - 2
            sp = sp + 1; st[sp] = ARITH[key](x, y)
            pc = pc + 5
        elseif h == 23 then st[sp] = -st[sp]; pc = pc + 1
        elseif h == 191 then st[sp] = (st[sp] == nil or st[sp] == false); pc = pc + 1
        elseif h == 229 then st[sp] = #st[sp]; pc = pc + 1
        elseif h == 79 then st[sp] = bit32.bnot(st[sp]); pc = pc + 1
        elseif h == 55 then -- CLOSURE
            local child = read32(code, pc+1)
            local cr = CHUNKS[child]
            local ups = nil
            if #cr.mdg > 0 then
                ups = {}
                for j, d in ipairs(cr.mdg) do
                    if d.k == 0 then
                        local c = F.ri[d.i]
                        if not c then c = {}; F.ri[d.i] = c end
                        ups[j] = c
                    else
                        ups[j] = F.zd[d.i]
                    end
                end
            end
            sp = sp + 1
            st[sp] = function(...) return spawn(child, ups, ...) end
            pc = pc + 5
        elseif h == 157 then -- MK (не используется)
            sp = sp + 1; st[sp] = nil; pc = pc + 5
        elseif h == 159 then -- FOR_PREP (числовой for: лимит, старт, шаг)
            local b = read32(code, pc+1); local a = read32(code, pc+5)
            local c = read32(code, pc+9); local d = read32(code, pc+13)
            local step, lim, start = st[sp], st[sp-1], st[sp-2]; sp = sp - 3
            F.vl[a] = start; F.vl[b] = lim; F.vl[c] = step; F.vl[d] = start
            pc = pc + 17
        elseif h == 169 then -- FOR_GEN (generic for: fn, state, ctrl)
            local b = read32(code, pc+1); local a = read32(code, pc+5)
            local c = read32(code, pc+9); local d = read32(code, pc+13)
            local ctrl, state, fn = st[sp], st[sp-1], st[sp-2]; sp = sp - 3
            F.vl[a] = fn; F.vl[b] = state; F.vl[c] = ctrl
            pc = pc + 17
        elseif h == 26 then -- PUSH_NILS
            local a = read32(code, pc+1)
            for k = 1, a do sp = sp + 1; st[sp] = nil end
            pc = pc + 5
        elseif h == 234 then -- JUMP (абсолютный)
            pc = read32(code, pc+1)
        elseif h == 131 then -- COND_JUMP (b=ложь, a=истина)
            local b = read32(code, pc+1); local a = read32(code, pc+5)
            local v = st[sp]; sp = sp - 1
            if v ~= nil and v ~= false then pc = a else pc = b end
        elseif h == 112 then -- RETURN
            local a = read32(code, pc+1)
            if a == 0 then
                local j = sp
                while st[j] ~= MARK_RET do j = j - 1 end
                local vals = {}
                for k = j+1, sp do vals[#vals+1] = st[k] end
                return table.unpack(vals, 1, #vals)
            elseif a == 1 then
                return
            elseif a == 2 then
                return st[sp]
            else
                local cnt = a - 1
                return table.unpack(st, sp - cnt + 1, sp)
            end
        else
            error("[AquaVM] неизвестный хендлер " .. tostring(h) .. " (байт " .. tostring(raw) .. ", pc=" .. pc .. ")")
        end
    end
end

-- ═══ 4. ЗАПУСК (chunk 0 — точка входа; корню — своя таблица upvalue, как _wvaYZ(p0,{})) ═══
return spawn(0, {})